using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace BlogApi;

[ApiController]
[Route("api/blogs")]
public class BlogsController(BlogContext db) : ControllerBase
{
    [HttpPost]
    public async Task<ActionResult<BlogDto>> CreateBlog([FromBody] BlogRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Name)) return BadRequest();

        var blog = new Blog { Id = Guid.NewGuid(), Name = request.Name };
        db.Blogs.Add(blog);
        await db.SaveChangesAsync();

        return CreatedAtAction(nameof(GetBlog), new { id = blog.Id }, BlogDto.From(blog));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<BlogDto>> GetBlog(Guid id)
    {
        var blog = await db.Blogs.FindAsync(id);
        return blog is null ? NotFound() : Ok(BlogDto.From(blog));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<BlogDto>> UpdateBlog(Guid id, [FromBody] BlogRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Name)) return BadRequest();

        var blog = await db.Blogs.FindAsync(id);
        if (blog is null) return NotFound();

        blog.Name = request.Name;
        await db.SaveChangesAsync();
        return Ok(BlogDto.From(blog));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> DeleteBlog(Guid id)
    {
        var blog = await db.Blogs.FindAsync(id);
        if (blog is null) return NotFound();

        db.Blogs.Remove(blog);
        await db.SaveChangesAsync();
        return NoContent();
    }

    [HttpPost("{blogId:guid}/posts")]
    public async Task<ActionResult<PostDto>> CreatePost(Guid blogId, [FromBody] PostRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Title)) return BadRequest();

        var blog = await db.Blogs.FindAsync(blogId);
        if (blog is null) return NotFound();

        var post = new Post { Id = Guid.NewGuid(), BlogId = blogId, Title = request.Title };
        db.Posts.Add(post);
        await db.SaveChangesAsync();

        return CreatedAtAction(nameof(PostsController.GetPost), "Posts", new { id = post.Id }, PostDto.From(post));
    }
}

