Design notes:
- `Post.Views` is server-owned. It is not in the post JSON, and it increments on each `GET /api/posts/{id}`.
- Creating a post under a missing blog returns 404. Deleting a blog cascades to its posts.
- Creates return 201 with a `Location` header. Missing resources return 404, and empty or whitespace `name` or `title` returns 400.
- Ids are generated server-side with `Guid.NewGuid()`.

```csharp
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;

public class Blog
{
    public Guid Id { get; set; }
    public string Name { get; set; } = "";
    public List<Post> Posts { get; set; } = new();
}

public class Post
{
    public Guid Id { get; set; }
    public Guid BlogId { get; set; }
    public Blog? Blog { get; set; }
    public string Title { get; set; } = "";
    public int Views { get; set; }
}

public record BlogDto(Guid Id, string Name);
public record BlogRequest(string? Name);

public record PostDto(Guid Id, Guid BlogId, string Title);
public record CreatePostRequest(string? Title);
public record UpdatePostRequest(Guid? BlogId, string? Title);

public class BlogContext(DbContextOptions<BlogContext> options) : DbContext(options)
{
    public DbSet<Blog> Blogs => Set<Blog>();
    public DbSet<Post> Posts => Set<Post>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(e =>
        {
            e.HasKey(x => x.Id);
            e.Property(x => x.Name).IsRequired();
            e.HasMany(x => x.Posts)
                .WithOne(p => p.Blog)
                .HasForeignKey(p => p.BlogId)
                .OnDelete(DeleteBehavior.Cascade);
        });

        modelBuilder.Entity<Post>(e =>
        {
            e.HasKey(x => x.Id);
            e.Property(x => x.Title).IsRequired();
            e.Property(x => x.Views).IsRequired();
            e.HasIndex(x => x.BlogId);
        });
    }
}

[ApiController]
[Route("api/blogs")]
public class BlogsController(BlogContext db) : ControllerBase
{
    [HttpPost]
    public async Task<ActionResult<BlogDto>> Create([FromBody] BlogRequest req, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(req.Name)) return BadRequest();

        var blog = new Blog { Id = Guid.NewGuid(), Name = req.Name };
        db.Blogs.Add(blog);
        await db.SaveChangesAsync(ct);

        var dto = new BlogDto(blog.Id, blog.Name);
        return CreatedAtAction(nameof(Get), new { id = blog.Id }, dto);
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<BlogDto>> Get(Guid id, CancellationToken ct)
    {
        var dto = await db.Blogs.AsNoTracking()
            .Where(b => b.Id == id)
            .Select(b => new BlogDto(b.Id, b.Name))
            .FirstOrDefaultAsync(ct);

        return dto is null ? NotFound() : Ok(dto);
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<BlogDto>> Update(Guid id, [FromBody] BlogRequest req, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(req.Name)) return BadRequest();

        var updated = await db.Blogs.Where(b => b.Id == id)
            .ExecuteUpdateAsync(s => s.SetProperty(b => b.Name, req.Name), ct);

        return updated == 0 ? NotFound() : Ok(new BlogDto(id, req.Name));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        await using var tx = await db.Database.BeginTransactionAsync(ct);

        await db.Posts.Where(p => p.BlogId == id).ExecuteDeleteAsync(ct);
        var deleted = await db.Blogs.Where(b => b.Id == id).ExecuteDeleteAsync(ct);

        if (deleted == 0) return NotFound();

        await tx.CommitAsync(ct);
        return NoContent();
    }
}

[ApiController]
[Route("api")]
public class PostsController(BlogContext db) : ControllerBase
{
    [HttpPost("blogs/{blogId:guid}/posts")]
    public async Task<ActionResult<PostDto>> Create(Guid blogId, [FromBody] CreatePostRequest req, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(req.Title)) return BadRequest();
        if (!await db.Blogs.AnyAsync(b => b.Id == blogId, ct)) return NotFound();

        var post = new Post { Id = Guid.NewGuid(), BlogId = blogId, Title = req.Title, Views = 0 };
        db.Posts.Add(post);
        await db.SaveChangesAsync(ct);

        var dto = new PostDto(post.Id, post.BlogId, post.Title);
        return CreatedAtAction(nameof(Get), new { id = post.Id }, dto);
    }

    [HttpGet("posts/{id:guid}")]
    public async Task<ActionResult<PostDto>> Get(Guid id, CancellationToken ct)
    {
        var viewed = await db.Posts.Where(p => p.Id == id)
            .ExecuteUpdateAsync(s => s.SetProperty(p => p.Views, p => p.Views + 1), ct);
        if (viewed == 0) return NotFound();

        var dto = await db.Posts.AsNoTracking()
            .Where(p => p.Id == id)
            .Select(p => new PostDto(p.Id, p.BlogId, p.Title))
            .FirstOrDefaultAsync(ct);

        return dto is null ? NotFound() : Ok(dto);
    }

    [HttpPut("posts/{id:guid}")]
    public async Task<ActionResult<PostDto>> Update(Guid id, [FromBody] UpdatePostRequest req, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(req.Title)) return BadRequest();

        if (req.BlogId is Guid newBlogId && !await db.Blogs.AnyAsync(b => b.Id == newBlogId, ct))
            return BadRequest("Blog not found.");

        var query = db.Posts.Where(p => p.Id == id);
        var updated = req.BlogId is Guid blogId
            ? await query.ExecuteUpdateAsync(s => s.SetProperty(p => p.Title, req.Title).SetProperty(p => p.BlogId, blogId), ct)
            : await query.ExecuteUpdateAsync(s => s.SetProperty(p => p.Title, req.Title), ct);

        if (updated == 0) return NotFound();

        var dto = await db.Posts.AsNoTracking()
            .Where(p => p.Id == id)
            .Select(p => new PostDto(p.Id, p.BlogId, p.Title))
            .FirstOrDefaultAsync(ct);

        return dto is null ? NotFound() : Ok(dto);
    }

    [HttpDelete("posts/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var deleted = await db.Posts.Where(p => p.Id == id).ExecuteDeleteAsync(ct);
        return deleted == 0 ? NotFound() : NoContent();
    }
}

public static class AppSetup
{
    public static void ConfigureServices(IServiceCollection services, string sqliteConnectionString)
    {
        services.AddDbContext<BlogContext>(o => o.UseSqlite(sqliteConnectionString));
    }
}
