// SupportTicketsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController(TicketsDbContext db) : ControllerBase
{
    [HttpPost]
    public async Task<ActionResult<TicketResponse>> Create([FromBody] TicketInput input, CancellationToken ct)
    {
        var key = Request.Headers["Idempotency-Key"].FirstOrDefault();
        if (!string.IsNullOrEmpty(key))
        {
            var existing = await db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.IdempotencyKey == key, ct);
            if (existing is not null) return Ok(ToResponse(existing));
        }

        var ticket = new Ticket
        {
            Id = Guid.NewGuid(),
            Subject = input.Subject,
            Priority = input.Priority,
            Escalated = input.Escalated,
            Category = input.Category,
            IdempotencyKey = string.IsNullOrEmpty(key) ? null : key
        };
        db.Tickets.Add(ticket);
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException) when (key is not null)
        {
            // A concurrent retry with the same key won the race.
            var dup = await db.Tickets.AsNoTracking().SingleAsync(t => t.IdempotencyKey == key, ct);
            return Ok(ToResponse(dup));
        }

        Response.Headers.ETag = $"\"{ticket.Version}\"";
        return CreatedAtAction(nameof(Get), new { id = ticket.Id }, ToResponse(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> Get(Guid id, CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        var updated = await db.Tickets.Where(t => t.Id == id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, now), ct);
        if (updated == 0) return NotFound();

        var ticket = await db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id, ct);
        if (ticket is null) return NotFound();

        Response.Headers.ETag = $"\"{ticket.Version}\"";
        return ToResponse(ticket);
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> Update(Guid id, [FromBody] TicketInput input, CancellationToken ct)
    {
        var ticket = await db.Tickets.FirstOrDefaultAsync(t => t.Id == id, ct);
        if (ticket is null) return NotFound();

        var ifMatch = Request.Headers.IfMatch.ToString();
        if (ifMatch.Length > 0 && ifMatch.Trim('"') != ticket.Version.ToString())
            return StatusCode(StatusCodes.Status412PreconditionFailed);

        ticket.Subject = input.Subject;
        ticket.Priority = input.Priority;
        ticket.Escalated = input.Escalated;
        ticket.Category = input.Category;
        ticket.Version++;

        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }

        Response.Headers.ETag = $"\"{ticket.Version}\"";
        return ToResponse(ticket);
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        await db.Tickets.Where(t => t.Id == id).ExecuteDeleteAsync(ct);
        return NoContent();
    }

    private static TicketResponse ToResponse(Ticket t) =>
        new(t.Id, t.Subject, t.Priority, t.Escalated, t.Category, t.ViewCount, t.LastViewedAt);
}
