using System.Security.Cryptography;
using System.Text;

public static class Canonical
{
    public static string Nfc(string s) => s.Normalize(NormalizationForm.FormC);

    public static string Blog(Guid id, string name) =>
        Tag($"{{\"id\":\"{id:D}\",\"name\":\"{Esc(name)}\"}}");

    public static string Post(Guid id, Guid blogId, string title) =>
        Tag($"{{\"id\":\"{id:D}\",\"blogId\":\"{blogId:D}\",\"title\":\"{Esc(title)}\"}}");

    static string Tag(string json) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(json)))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";

    static string Esc(string s)
    {
        var sb = new StringBuilder();
        foreach (var c in Nfc(s))
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append($"\\u{(int)c:x4}");
                    else sb.Append(c);
                    break;
            }
        return sb.ToString();
    }
}
