    public Guid Id { get; set; }
    public Guid BlogId { get; set; }
    public string Title { get; set; } = "";
    public int Views { get; set; }
    public string ETag { get; set; } = "";
    public string CreateHash { get; set; } = "";
    public DateTime? Tombstone { get; set; }
}

public record BlogRequest(Guid? Id, string? Name);
public record BlogResponse(Guid Id, string Name);
public record PostRequest(Guid? Id, Guid? BlogId, string? Title);
public record PostResponse(Guid Id, Guid BlogId, string Title);

public class BlogDbContext(DbContextOptions<BlogDbContext> options) : DbContext(options)
{
