    {
        m.Entity<Blog>(b =>
        {
            b.HasKey(x => x.Pk);
            b.HasIndex(x => x.Id).IsUnique();
            b.Property(x => x.Name).IsRequired();
            b.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
            b.Property(x => x.CreateHash).IsRequired().Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            b.HasQueryFilter(x => x.Tombstone == null);
        });

        m.Entity<Post>(p =>
        {
            p.HasKey(x => x.Pk);
            p.HasIndex(x => x.Id).IsUnique();
            p.Property(x => x.Title).IsRequired();
            p.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
