```csharp
using System.ComponentModel.DataAnnotations;
using System.Text.Json;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

public abstract class ApiBaseController : ControllerBase
{
    protected static IActionResult Fail(int status, string title) =>
        new ContentResult
        {
            StatusCode = status,
            ContentType = "application/problem+json",
            Content = JsonSerializer.Serialize(new { type = "about:blank", title, status })
        };

    protected IActionResult Precondition(string etag)
    {
        Response.Headers["ETag"] = etag;
        return Fail(412, "Precondition Failed");
    }

    protected static bool Valid(string? s) => !string.IsNullOrWhiteSpace(s);
}

[Route("api/blogs")]
public class BlogsController(BlogDbContext db) : ApiBaseController
{
    [HttpPost]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] BlogRequest? body, CancellationToken ct)
    {
        if (body is null || body.Id is null || !Valid(body.Name)) return Fail(400, "Invalid blog");
        var id = body.Id.Value;
        var name = Canonical.Nfc(body.Name!);
        var etag = Canonical.Blog(id, name);
        db.Blogs.Add(new Blog { Id = id, Name = name, ETag = etag, CreateHash = etag });
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (ex.InnerException is SqliteException { SqliteExtendedErrorCode: 2067 })
        {
            db.ChangeTracker.Clear();
            var existing = await db.Blogs.IgnoreQueryFilters().AsNoTracking().FirstAsync(b => b.Id == id, ct);
            if (existing.Tombstone is not null) return Fail(410, "Blog deleted");
            if (existing.CreateHash != etag) return Fail(409, "Blog id already used with different content");
            Response.Headers["ETag"] = existing.ETag;
            return Ok(new BlogResponse(existing.Id, existing.Name));
        }
        Response.Headers["ETag"] = etag;
        return Created($"/api/blogs/{id:D}", new BlogResponse(id, name));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var blog = await db.Blogs.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(b => b.Id == id, ct);
        if (blog is null) return Fail(404, "Blog not found");
        if (blog.Tombstone is not null) return Fail(410, "Blog deleted");
        Response.Headers["ETag"] = blog.ETag;
        if (Request.Headers["If-None-Match"] == blog.ETag) return StatusCode(304);
        return Ok(new BlogResponse(blog.Id, blog.Name));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromBody] BlogRequest? body,
        [Required, FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken ct)
    {
        if (body is null || body.Id != id || !Valid(body.Name)) return Fail(400, "Invalid blog");
        if (ifMatch is null) return Fail(428, "If-Match header required");
        var name = Canonical.Nfc(body.Name!);
        var etag = Canonical.Blog(id, name);
        var blog = await db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.Id == id, ct);
        if (blog is null) return Fail(404, "Blog not found");
        if (blog.Tombstone is not null) return Fail(410, "Blog deleted");
        if (blog.ETag == etag) { Response.Headers["ETag"] = etag; return NoContent(); }
        if (ifMatch != "*" && ifMatch != blog.ETag) return Precondition(blog.ETag);
        blog.Name = name;
        blog.ETag = etag;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            return await Update(id, body, ifMatch, ct);
        }
        Response.Headers["ETag"] = etag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [Required, FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken ct)
    {
        if (ifMatch is null) return Fail(428, "If-Match header required");
        var blog = await db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.Id == id, ct);
        if (blog is null || blog.Tombstone is not null) return NoContent();
        if (ifMatch != "*" && ifMatch != blog.ETag) return Precondition(blog.ETag);
        var now = DateTime.UtcNow;
        blog.Tombstone = now;
        foreach (var post in await db.Posts.Where(p => p.BlogId == id).ToListAsync(ct)) post.Tombstone = now;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            return await Delete(id, ifMatch, ct);
        }
        return NoContent();
    }
}

