            if (existing.Tombstone is not null) return Fail(410, "Post deleted");
            if (existing.BlogId != blogId || existing.CreateHash != etag) return Fail(409, "Post id already used with different content");
            Response.Headers["ETag"] = existing.ETag;
            return Ok(new PostResponse(existing.Id, existing.BlogId, existing.Title));
