using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public class Ticket
{
    public int Id { get; set; }
    public Guid PublicId { get; set; }
    public string Subject { get; set; } = "";
    public int Priority { get; set; }
    public bool Escalated { get; set; }
    public string Category { get; set; } = "";
    public string ETag { get; set; } = "";
    public string RequestHash { get; set; } = "";
    public DateTime? DeletedAt { get; set; }
    public int ViewCount { get; set; }
    public DateTime? LastViewedAt { get; set; }

    public string ComputeETag() => TicketEtag.Of(PublicId, Subject, Priority, Escalated, Category);
}

public sealed record TicketDto(Guid Id, string Subject, int Priority, bool Escalated, string Category);

public sealed class TicketInput
{
    public Guid? Id { get; set; }
    public string? Subject { get; set; }
    public int? Priority { get; set; }
    public bool? Escalated { get; set; }
    public string? Category { get; set; }

    public bool IsValid => Id is not null && !string.IsNullOrEmpty(Subject) && Priority is not null && Escalated is not null && Category is not null;

    public Ticket ToTicket()
    {
        var t = new Ticket
        {
            PublicId = Id!.Value,
            Subject = Subject!.Normalize(NormalizationForm.FormC),
            Priority = Priority!.Value,
            Escalated = Escalated!.Value,
            Category = Category!.Normalize(NormalizationForm.FormC)
        };
        t.ETag = t.ComputeETag();
        return t;
    }
}

public static class TicketEtag
{
    public static string Of(Guid id, string subject, int priority, bool escalated, string category)
    {
        var json = "{\"id\":\"" + id.ToString("D") + "\",\"subject\":" + Str(subject)
            + ",\"priority\":" + priority.ToString(CultureInfo.InvariantCulture)
            + ",\"escalated\":" + (escalated ? "true" : "false")
            + ",\"category\":" + Str(category) + "}";
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(json));
        return "\"" + Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    private static string Str(string value)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in value.Normalize(NormalizationForm.FormC))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (char.IsControl(c)) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }
}
