using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

[Route("api/support-tickets")]
public sealed class SupportTicketsController(TicketsDbContext db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(TicketDto), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(TicketDto), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] TicketInput? input, CancellationToken ct)
    {
        if (input is null || !input.IsValid) return Fail(400, "Invalid ticket.");

        var incoming = input.ToTicket();
        incoming.RequestHash = incoming.ETag;
        db.Tickets.Add(incoming);

        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (ex.InnerException is SqliteException { SqliteExtendedErrorCode: 2067 })
        {
            var existing = await Find(incoming.PublicId, ct);
            if (existing is null) return Fail(409, "Ticket id already exists.");
            if (existing.DeletedAt is not null) return Fail(410, "Ticket was deleted.");
            Response.Headers.ETag = existing.ETag;
            if (existing.RequestHash == incoming.RequestHash) return Ok(ToDto(existing));
            return Fail(409, "Ticket id already exists with different content.");
        }

        Response.Headers.ETag = incoming.ETag;
        return Created($"/api/support-tickets/{incoming.PublicId}", ToDto(incoming));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(TicketDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, [FromHeader(Name = "If-None-Match")] string? ifNoneMatch, CancellationToken ct)
    {
        var ticket = await Find(id, ct);
        if (ticket is null) return Fail(404, "Ticket not found.");
        if (ticket.DeletedAt is not null) return Fail(410, "Ticket was deleted.");

        Response.Headers.ETag = ticket.ETag;
        if (Matches(ifNoneMatch, ticket.ETag)) return StatusCode(StatusCodes.Status304NotModified);

        await db.Tickets.Where(t => t.Id == ticket.Id).ExecuteUpdateAsync(s => s
            .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
            .SetProperty(t => t.LastViewedAt, DateTime.UtcNow), ct);

        return Ok(ToDto(ticket));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody] TicketInput? input, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (input is null || !input.IsValid || input.Id != id) return Fail(400, "Invalid ticket or id mismatch.");
        if (ifMatch is null) return Fail(428, "If-Match header is required.");

        var incoming = input.ToTicket();
        var current = await db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(t => t.PublicId == id, ct);
        if (current is null) return Fail(404, "Ticket not found.");
        if (current.DeletedAt is not null) return Fail(410, "Ticket was deleted.");

        if (current.ETag == incoming.ETag)
        {
            Response.Headers.ETag = current.ETag;
            return NoContent();
        }
        if (!Matches(ifMatch, current.ETag)) return await Stale(id, ct);

        current.Subject = incoming.Subject;
        current.Priority = incoming.Priority;
        current.Escalated = incoming.Escalated;
        current.Category = incoming.Category;
        current.ETag = incoming.ETag;

        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await Stale(id, ct);
        }

        Response.Headers.ETag = current.ETag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (ifMatch is null) return Fail(428, "If-Match header is required.");

        var current = await db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(t => t.PublicId == id, ct);
        if (current is null || current.DeletedAt is not null) return NoContent();
        if (!Matches(ifMatch, current.ETag)) return await Stale(id, ct);

        current.DeletedAt = DateTime.UtcNow;
        current.ETag = "\"deleted-" + Guid.NewGuid().ToString("N") + "\"";

        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var latest = await Find(id, ct);
            return latest is { DeletedAt: null } ? await Stale(id, ct) : NoContent();
        }

        return NoContent();
    }

    private Task<Ticket?> Find(Guid id, CancellationToken ct) =>
        db.Tickets.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(t => t.PublicId == id, ct);

    private async Task<IActionResult> Stale(Guid id, CancellationToken ct)
    {
        var latest = await Find(id, ct);
        if (latest is null) return Fail(404, "Ticket not found.");
        if (latest.DeletedAt is not null) return Fail(410, "Ticket was deleted.");
        Response.Headers.ETag = latest.ETag;
        return Fail(412, "The ETag does not match the current version.");
    }

    private static bool Matches(string? header, string etag) =>
        header is not null && (header.Trim() == "*" || header.Split(',').Any(v => v.Trim() == etag));

    private static TicketDto ToDto(Ticket t) => new(t.PublicId, t.Subject, t.Priority, t.Escalated, t.Category);

    private static ObjectResult Fail(int status, string title) =>
        new(new ProblemDetails { Status = status, Title = title }) { StatusCode = status, ContentType = "application/problem+json" };
}
