[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly AppDbContext _db;
    public SupportTicketsController(AppDbContext db) => _db = db;

    private static bool Valid(TicketRequest? r) =>
        r != null && !string.IsNullOrWhiteSpace(r.Subject) && r.Category != null && r.Priority != null;

    private static bool Same(Ticket t, TicketRequest r) =>
        t.Subject == r.Subject && t.Category == r.Category && t.Priority == r.Priority!.Value
        && t.Escalated == (r.Escalated ?? false);

    private IActionResult WithEtag(Ticket t, IActionResult result)
    {
        Response.Headers.ETag = $"\"{t.Version}\"";
        return result;
    }

    private static Guid? ParseEtag(string? header)
    {
        if (string.IsNullOrWhiteSpace(header)) return null;
        var s = header.Trim();
        if (s == "*") return null;
        if (s.StartsWith("W/")) s = s[2..];
        s = s.Trim('"');
        return Guid.TryParse(s, out var g) ? g : Guid.Empty;
    }

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] TicketRequest? req, CancellationToken ct)
    {
        if (!Valid(req)) return BadRequest();
        var key = Request.Headers["Idempotency-Key"].FirstOrDefault();
        if (string.IsNullOrWhiteSpace(key)) key = null;

        if (key != null)
        {
            var rec = await _db.IdempotencyRecords.AsNoTracking().FirstOrDefaultAsync(r => r.Key == key, ct);
            if (rec != null)
            {
                var prev = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == rec.TicketId, ct);
                return prev == null ? Conflict() : WithEtag(prev, Ok(TicketResponse.From(prev)));
            }
        }

        var id = req!.Id is { } g && g != Guid.Empty ? g : Guid.NewGuid();
        var existing = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id, ct);
        if (existing != null)
            return Same(existing, req) ? WithEtag(existing, Ok(TicketResponse.From(existing))) : Conflict();

        var ticket = new Ticket
        {
            Id = id, Subject = req.Subject!, Priority = req.Priority!.Value,
            Escalated = req.Escalated ?? false, Category = req.Category!
        };
        _db.Tickets.Add(ticket);
        if (key != null) _db.IdempotencyRecords.Add(new IdempotencyRecord { Key = key, TicketId = id });
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();
            var other = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id, ct);
            if (other != null && (key != null || Same(other, req)))
                return WithEtag(other, Ok(TicketResponse.From(other)));
            return Conflict();
        }
        Response.Headers.Location = $"/api/support-tickets/{id}";
        return WithEtag(ticket, Created($"/api/support-tickets/{id}", TicketResponse.From(ticket)));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        var n = await _db.Tickets.Where(t => t.Id == id).ExecuteUpdateAsync(s => s
            .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
            .SetProperty(t => t.LastViewedAt, now), ct);
        if (n == 0) return NotFound();
        var t = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, ct);
        if (t == null) return NotFound();
        return WithEtag(t, Ok(TicketResponse.From(t)));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] TicketRequest? req, CancellationToken ct)
    {
        if (!Valid(req)) return BadRequest();
        var expected = ParseEtag(Request.Headers.IfMatch.FirstOrDefault());
        var newVersion = Guid.NewGuid();
        var subject = req!.Subject!;
        var category = req.Category!;
        var priority = req.Priority!.Value;
        var escalated = req.Escalated ?? false;

        var q = _db.Tickets.Where(t => t.Id == id);
        if (expected != null) q = q.Where(t => t.Version == expected.Value);

        var n = await q.ExecuteUpdateAsync(s => s
            .SetProperty(t => t.Subject, subject)
            .SetProperty(t => t.Category, category)
            .SetProperty(t => t.Priority, priority)
            .SetProperty(t => t.Escalated, escalated)
            .SetProperty(t => t.Version, newVersion), ct);

        if (n == 0)
        {
            var exists = await _db.Tickets.AnyAsync(t => t.Id == id, ct);
            return exists ? StatusCode(StatusCodes.Status412PreconditionFailed) : NotFound();
        }
        var updated = await _db.Tickets.AsNoTracking().FirstAsync(t => t.Id == id, ct);
        return WithEtag(updated, Ok(TicketResponse.From(updated)));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var expected = ParseEtag(Request.Headers.IfMatch.FirstOrDefault());
        var q = _db.Tickets.Where(t => t.Id == id);
        if (expected != null) q = q.Where(t => t.Version == expected.Value);
        var n = await q.ExecuteDeleteAsync(ct);
        if (n == 0)
        {
            var exists = await _db.Tickets.AnyAsync(t => t.Id == id, ct);
            return exists ? StatusCode(StatusCodes.Status412PreconditionFailed) : NotFound();
        }
        return NoContent();
    }
}
```

Design notes:
- **Retries on POST:** A client may supply `id`. Re-posting the same id with the same content returns 200 with the existing ticket instead of creating a duplicate. The same id with different content returns 409. An `Idempotency-Key` header is also supported for POSTs that don't carry an id.
- **Concurrent edits:** Every ticket has a `Version` that changes on each PUT and is returned as the `ETag`. If a client sends `If-Match` on a PUT or DELETE, a stale version gets 412. Without `If-Match`, PUT is last-write-wins. Updates are single atomic SQL statements, so there are no lost updates on the same row.
- **View counters:** `ViewCount` and `LastViewedAt` are updated by GET with an atomic SQL increment. PUT never touches these columns, and clients can't set them.

