public static class Canon
{
    public static string? Norm(string? s)
    {
        if (s is null) return null;
        try { return s.Normalize(NormalizationForm.FormC); }
        catch (ArgumentException) { return null; }
    }

    static void Str(StringBuilder sb, string s)
    {
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }

    static string Hash(string json) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(json)))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";

    public static string BlogTag(Guid id, string name)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("D")).Append("\",\"name\":");
        Str(sb, name);
        sb.Append('}');
        return Hash(sb.ToString());
    }

    public static string PostTag(Guid id, Guid blogId, string title)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("D")).Append("\",\"blogId\":\"").Append(blogId.ToString("D")).Append("\",\"title\":");
        Str(sb, title);
        sb.Append('}');
        return Hash(sb.ToString());
    }
