    protected static bool IfMatchOk(string? header, string current) =>
        header != null && header.Split(',').Select(s => s.Trim()).Any(s => s == "*" || s == current);

    protected bool NoneMatchHit(string current) =>
        Request.Headers.IfNoneMatch.ToString().Split(',').Select(s => s.Trim())
            .Any(s => s == "*" || (s.StartsWith("W/") ? s[2..] : s) == current);

    protected static bool IsUnique(DbUpdateException e) =>
        e.InnerException is SqliteException { SqliteExtendedErrorCode: 2067 or 1555 };
}

