public static class Canon
{
    public static string Json(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s.Normalize(NormalizationForm.FormC))
            sb.Append(c switch
            {
                '"' => "\\\"",
                '\\' => "\\\\",
                '\b' => "\\b",
                '\f' => "\\f",
                '\n' => "\\n",
                '\r' => "\\r",
                '\t' => "\\t",
                _ when char.IsControl(c) => $"\\u{(int)c:x4}",
                _ => c.ToString()
            });
        return sb.Append('"').ToString();
    }

    public static string Num(decimal d) => d.Normalize().ToString(CultureInfo.InvariantCulture);

    public static string Warehouse(Guid id, string code, int cap) =>
        $"{{\"id\":{Json(id.ToString("D"))},\"code\":{Json(code)},\"capacityCubicMeters\":{cap.ToString(CultureInfo.InvariantCulture)}}}";

    public static string Shipment(Guid id, Guid warehouseId, string reference, decimal weight, bool fragile) =>
        $"{{\"id\":{Json(id.ToString("D"))},\"warehouseId\":{Json(warehouseId.ToString("D"))},\"reference\":{Json(reference)},\"weightKg\":{Num(weight)},\"fragile\":{(fragile ? "true" : "false")}}}";

    public static string ETag(string json) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(json))).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
}

public static class Api
{
    static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

    public static ContentResult Problem(int status, string title) => new()
    {
        StatusCode = status,
        ContentType = "application/problem+json",
        Content = JsonSerializer.Serialize(new ProblemDetails { Status = status, Title = title }, JsonOptions)
    };

    public static bool Matches(string ifMatch, string etag) =>
        ifMatch == "*" || ifMatch.Split(',').Any(t => t.Trim() == etag);

    public static bool NoneMatch(string ifNoneMatch, string etag) =>
        ifNoneMatch == "*" || ifNoneMatch.Split(',').Any(t => t.Trim() == etag);
}
