[ApiController]
public sealed class WarehousesController(AppDbContext db) : ControllerBase
{
    [HttpPost("api/warehouses")]
    [ProducesResponseType(typeof(WarehouseDto), 201)]
    [ProducesResponseType(typeof(WarehouseDto), 200)]
    [ProducesResponseType(typeof(ProblemDetails), 400, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 409, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] WarehouseBody? body, CancellationToken ct)
    {
        if (body is not { Id: not null, Code: { Length: > 0 }, CapacityCubicMeters: >= 0 })
            return Api.Problem(400, "Invalid warehouse.");
        var id = body.Id!.Value;
        var code = body.Code!;
        var cap = body.CapacityCubicMeters!.Value;
        var etag = Canon.ETag(Canon.Warehouse(id, code, cap));

        db.Depots.Add(new Depot { PublicId = id, Code = code, CapacityCubicMeters = cap, ETag = etag, CreateHash = etag, LastAuditAt = DateTime.UtcNow });
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            db.ChangeTracker.Clear();
            var old = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(d => d.PublicId == id, ct);
            if (old is null) throw;
            if (old.DeletedAt is not null) return Api.Problem(410, "Warehouse was deleted.");
            if (old.CreateHash != etag) return Api.Problem(409, "Warehouse id already exists with different content.");
            Response.Headers["ETag"] = old.ETag;
            return Ok(ToDto(old));
        }

        Response.Headers["ETag"] = etag;
        Response.Headers["Location"] = $"/api/warehouses/{id}";
        return StatusCode(201, new WarehouseDto(id, code, cap));
    }

    [HttpGet("api/warehouses/{id:guid}")]
    [ProducesResponseType(typeof(WarehouseDto), 200)]
    [ProducesResponseType(304)]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var d = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (d is null) return Api.Problem(404, "Warehouse not found.");
        if (d.DeletedAt is not null) return Api.Problem(410, "Warehouse was deleted.");
        Response.Headers["ETag"] = d.ETag;
        if (Api.NoneMatch(Request.Headers["If-None-Match"].ToString(), d.ETag)) return StatusCode(304);
        return Ok(ToDto(d));
    }

    [HttpPut("api/warehouses/{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 400, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 412, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 428, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromBody] WarehouseBody? body, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (body is not { Id: not null, Code: { Length: > 0 }, CapacityCubicMeters: >= 0 } || body.Id != id)
            return Api.Problem(400, "Invalid warehouse or id mismatch.");
        if (string.IsNullOrEmpty(ifMatch)) return Api.Problem(428, "If-Match header is required.");
        var code = body.Code!;
        var cap = body.CapacityCubicMeters!.Value;
        var etag = Canon.ETag(Canon.Warehouse(id, code, cap));

        var d = await db.Depots.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (d is null) return Api.Problem(404, "Warehouse not found.");
        if (d.DeletedAt is not null) return Api.Problem(410, "Warehouse was deleted.");
        if (d.ETag == etag)
        {
            Response.Headers["ETag"] = etag;
            return NoContent();
        }
        if (!Api.Matches(ifMatch, d.ETag))
        {
            Response.Headers["ETag"] = d.ETag;
            return Api.Problem(412, "ETag does not match the current version.");
        }

        d.Code = code;
        d.CapacityCubicMeters = cap;
        d.ETag = etag;
        d.LastAuditAt = DateTime.UtcNow;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var cur = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (cur is null) return Api.Problem(404, "Warehouse not found.");
            if (cur.DeletedAt is not null) return Api.Problem(410, "Warehouse was deleted.");
            Response.Headers["ETag"] = cur.ETag;
            if (cur.ETag == etag) return NoContent();
            return Api.Problem(412, "ETag does not match the current version.");
        }

        Response.Headers["ETag"] = etag;
        return NoContent();
