    [HttpDelete("api/warehouses/{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 412, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 428, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
