        {
            Response.Headers["ETag"] = d.ETag;
            return Api.Problem(412, "ETag does not match the current version.");
        }

        var now = DateTime.UtcNow;
        d.DeletedAt = now;
        d.LastAuditAt = now;
        await using var tx = await db.Database.BeginTransactionAsync(ct);
        try
        {
