    public async Task<IActionResult> Create(Guid warehouseId, [FromBody] ShipmentBody? body, CancellationToken ct)
    {
        if (body is not { Id: not null, WarehouseId: not null, Reference: { Length: > 0 }, WeightKg: >= 0m, Fragile: not null } || body.WarehouseId != warehouseId)
            return Api.Problem(400, "Invalid shipment or warehouse id mismatch.");
        var id = body.Id!.Value;
        var reference = body.Reference!;
        var weight = body.WeightKg!.Value;
        var fragile = body.Fragile!.Value;
        var etag = Canon.ETag(Canon.Shipment(id, warehouseId, reference, weight, fragile));

        var parent = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == warehouseId, ct);
        if (parent is null) return Api.Problem(404, "Warehouse not found.");
        if (parent.DeletedAt is not null) return Api.Problem(410, "Warehouse was deleted.");

        db.Consignments.Add(new Consignment { PublicId = id, DepotId = parent.Id, Reference = reference, WeightKg = weight, Fragile = fragile, ETag = etag, CreateHash = etag });
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            db.ChangeTracker.Clear();
            var old = await db.Consignments.IgnoreQueryFilters().Include(c => c.Depot).AsNoTracking().FirstOrDefaultAsync(c => c.PublicId == id, ct);
            if (old is null) throw;
            if (old.DeletedAt is not null) return Api.Problem(410, "Shipment was deleted.");
            if (old.Depot.PublicId != warehouseId || old.CreateHash != etag) return Api.Problem(409, "Shipment id already exists with different content or warehouse.");
            Response.Headers["ETag"] = old.ETag;
            return Ok(ToDto(old));
        }

        Response.Headers["ETag"] = etag;
        Response.Headers["Location"] = $"/api/shipments/{id}";
        return StatusCode(201, new ShipmentDto(id, warehouseId, reference, weight, fragile));
