public static class TicketCanon
{
    public static string Norm(string s) => s.Normalize(NormalizationForm.FormC);

    public static string Canonical(Guid id, string subject, int priority, bool escalated, string category)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":");
        Str(sb, id.ToString("D").ToLowerInvariant());
        sb.Append(",\"subject\":");
        Str(sb, Norm(subject));
        sb.Append(",\"priority\":").Append(priority.ToString(CultureInfo.InvariantCulture));
        sb.Append(",\"escalated\":").Append(escalated ? "true" : "false");
        sb.Append(",\"category\":");
        Str(sb, Norm(category));
        sb.Append('}');
        return sb.ToString();
    }

    static void Str(StringBuilder sb, string s)
    {
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }

    public static string Hash(string canonical)
    {
        var h = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        var b64 = Convert.ToBase64String(h).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + b64 + "\"";
    }
}

