[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly AppDbContext _db;
    public SupportTicketsController(AppDbContext db) => _db = db;

    static bool Valid(TicketRequest? r) =>
        r != null && r.Id.HasValue && r.Id.Value != Guid.Empty && !string.IsNullOrWhiteSpace(r.Subject)
        && r.Priority.HasValue && r.Escalated.HasValue && r.Category != null;

    static string HashOf(TicketRequest r) =>
        TicketCanon.Hash(TicketCanon.Canonical(r.Id!.Value, r.Subject!, r.Priority!.Value, r.Escalated!.Value, r.Category!));

    static TicketResponse ToDto(Ticket t) => new()
    {
        Id = t.PublicId, Subject = t.Subject, Priority = t.Priority, Escalated = t.Escalated, Category = t.Category
    };

    static bool Matches(string header, string etag)
    {
        foreach (var part in header.Split(','))
        {
            var p = part.Trim();
            if (p == "*" || p == etag) return true;
        }
        return false;
    }

    private IActionResult Err(int status, string title) => Problem(title: title, statusCode: status);

    private IActionResult Stale(string etag)
    {
        Response.Headers.ETag = etag;
        return Err(412, "Precondition failed");
    }

    [HttpPost]
    [ProducesResponseType<TicketResponse>(201)]
    [ProducesResponseType<TicketResponse>(200)]
    [ProducesResponseType<ProblemDetails>(400, "application/problem+json")]
    [ProducesResponseType<ProblemDetails>(409, "application/problem+json")]
    [ProducesResponseType<ProblemDetails>(410, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] TicketRequest? body, CancellationToken ct)
    {
        if (!Valid(body)) return Err(400, "Invalid request body");
        var hash = HashOf(body!);
        var id = body!.Id!.Value;
        var ticket = new Ticket
        {
            PublicId = id,
            Subject = TicketCanon.Norm(body.Subject!),
            Priority = body.Priority!.Value,
            Escalated = body.Escalated!.Value,
            Category = TicketCanon.Norm(body.Category!),
            ETag = hash,
            CreateHash = hash
        };
        _db.Tickets.Add(ticket);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();
            var existing = await _db.Tickets.IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(t => t.PublicId == id, ct);
            if (existing == null) throw;
            if (existing.DeletedAt != null) return Err(410, "Ticket was deleted");
            if (existing.CreateHash != hash) return Err(409, "Ticket exists with different content");
            Response.Headers.ETag = existing.ETag;
            return Ok(ToDto(existing));
        }
        Response.Headers.ETag = ticket.ETag;
        return Created($"/api/support-tickets/{id}", ToDto(ticket));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType<TicketResponse>(200)]
    [ProducesResponseType(304)]
    [ProducesResponseType<ProblemDetails>(404, "application/problem+json")]
    [ProducesResponseType<ProblemDetails>(410, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var t = await _db.Tickets.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t == null) return Err(404, "Ticket not found");
        if (t.DeletedAt != null) return Err(410, "Ticket was deleted");
        var now = DateTime.UtcNow;
        await _db.Tickets.Where(x => x.Id == t.Id)
            .ExecuteUpdateAsync(s => s.SetProperty(x => x.ViewCount, x => x.ViewCount + 1)
                                      .SetProperty(x => x.LastViewedAt, now), ct);
        Response.Headers.ETag = t.ETag;
        if (Request.Headers.TryGetValue("If-None-Match", out var inm) && inm.Count > 0
            && Matches(string.Join(",", inm.ToArray()), t.ETag))
            return StatusCode(304);
        return Ok(ToDto(t));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType<ProblemDetails>(400, "application/problem+json")]
    [ProducesResponseType<ProblemDetails>(404, "application/problem+json")]
    [ProducesResponseType<ProblemDetails>(410, "application/problem+json")]
    [ProducesResponseType<ProblemDetails>(412, "application/problem+json")]
    [ProducesResponseType<ProblemDetails>(428, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromBody] TicketRequest? body,
        [FromHeader(Name = "If-Match")][Required] string? ifMatch, CancellationToken ct)
    {
        if (!Valid(body) || body!.Id!.Value != id) return Err(400, "Invalid request body");
        if (string.IsNullOrWhiteSpace(ifMatch)) return Err(428, "If-Match header is required");
        var newEtag = HashOf(body);

        var t = await _db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t == null) return Err(404, "Ticket not found");
        if (t.DeletedAt != null) return Err(410, "Ticket was deleted");
        if (t.ETag == newEtag)
        {
            Response.Headers.ETag = t.ETag;
            return NoContent();
        }
        if (!Matches(ifMatch, t.ETag)) return Stale(t.ETag);

        t.Subject = TicketCanon.Norm(body.Subject!);
        t.Priority = body.Priority!.Value;
        t.Escalated = body.Escalated!.Value;
