            var cur = await _db.Tickets.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (cur == null) return Err(404, "Ticket not found");
            if (cur.DeletedAt != null) return Err(410, "Ticket was deleted");
            if (cur.ETag == newEtag)
            {
                Response.Headers.ETag = cur.ETag;
                return NoContent();
