    [ProducesResponseType<ProblemDetails>(412, "application/problem+json")]
    [ProducesResponseType<ProblemDetails>(428, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")][Required] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch)) return Err(428, "If-Match header is required");
        var t = await _db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t == null || t.DeletedAt != null) return NoContent();
        if (!Matches(ifMatch, t.ETag)) return Stale(t.ETag);
