        r.Headers.TryGetValue("Idempotency-Key", out var v) && !string.IsNullOrWhiteSpace(v.ToString()) ? v.ToString() : null;

    public static Guid? IfMatch(HttpRequest r)
    {
        if (!r.Headers.TryGetValue("If-Match", out var v)) return null;
        var s = v.ToString().Trim();
        if (s == "*" || s.Length == 0) return null;
        if (s.StartsWith("W/")) s = s[2..];
        return Guid.TryParse(s.Trim('"'), out var g) ? g : Guid.Empty;
    }

    public static void ETag(HttpResponse r, Guid version) => r.Headers.ETag = $"\"{version}\"";
