    {
        var rec = await _db.IdempotencyRecords.AsNoTracking().FirstOrDefaultAsync(x => x.Scope == scope && x.Key == key, ct);
        if (rec == null) return null;
        var d = await _db.Depots.AsNoTracking().FirstOrDefaultAsync(x => x.Id == rec.ResourceId, ct);
        if (d == null) return Conflict();
        Http.ETag(Response, d.Version);
        return CreatedAtAction(nameof(Get), new { id = d.Id }, ToDto(d));
