        if (d == null) return NotFound();
        Http.ETag(Response, d.Version);
        return Ok(ToDto(d));
    }

    [HttpPut("api/warehouses/{id:guid}")]
    public async Task<IActionResult> Put(Guid id, [FromBody] WarehouseRequest req, CancellationToken ct)
    {
        var ifMatch = Http.IfMatch(Request);
        for (var attempt = 0; attempt < 10; attempt++)
        {
            var d = await _db.Depots.FirstOrDefaultAsync(x => x.Id == id, ct);
            if (d == null) return NotFound();
            if (ifMatch != null && d.Version != ifMatch.Value) return StatusCode(StatusCodes.Status412PreconditionFailed);
            d.Code = req.Code!;
            d.CapacityCubicMeters = req.CapacityCubicMeters!.Value;
            d.LastAuditAt = DateTime.UtcNow;
            d.Version = Guid.NewGuid();
