                Http.ETag(Response, d.Version);
                return Ok(ToDto(d));
            }
            catch (DbUpdateConcurrencyException)
            {
                _db.ChangeTracker.Clear();
                if (ifMatch != null)
                {
                    if (!await _db.Depots.AnyAsync(x => x.Id == id, ct)) return NotFound();
