            || r.Reference is null || r.WeightKg is null || r.WeightKg < 0 || r.Fragile is null) return null;
        return new ShipmentData(r.Id.Value, r.WarehouseId.Value, Canon.Nfc(r.Reference), Canon.Norm(r.WeightKg.Value), r.Fragile.Value);
    }
    public string ETag() => Canon.Hash($"{{\"id\":\"{Canon.G(Id)}\",\"warehouseId\":\"{Canon.G(WarehouseId)}\",\"reference\":{Canon.Str(Reference)},\"weightKg\":{Canon.Dec(Weight)},\"fragile\":{(Fragile ? "true" : "false")}}}");
}

public static class Canon
{
    public static string G(Guid g) => g.ToString("D").ToLowerInvariant();
    public static string Nfc(string s) => s.Normalize(NormalizationForm.FormC);
    public static decimal Norm(decimal d) => d / 1.0000000000000000000000000000m;
    public static string Dec(decimal d) => Norm(d).ToString(CultureInfo.InvariantCulture);

    public static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }

    public static string Hash(string json)
    {
        var h = SHA256.HashData(Encoding.UTF8.GetBytes(json));
        var b64 = Convert.ToBase64String(h).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + b64 + "\"";
    }
}

public static class Http
{
    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var raw in header.Split(','))
        {
            var t = raw.Trim();
            if (t == "*") return true;
            if (t.StartsWith("W/")) t = t[2..];
            if (t == etag) return true;
        }
        return false;
    }

    public static bool IsUnique(DbUpdateException e) =>
        e.InnerException is SqliteException { SqliteErrorCode: 19 } s && s.Message.Contains("UNIQUE", StringComparison.OrdinalIgnoreCase);

    public static IActionResult Err(int status, string title)
    {
        var r = new ObjectResult(new ProblemDetails { Status = status, Title = title }) { StatusCode = status };
        r.ContentTypes.Add("application/problem+json");
        return r;
    }
}

