    [ProducesResponseType<ProblemDetails>(StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] WarehouseRequest? body, CancellationToken ct)
    {
        var data = WarehouseData.From(body);
        if (data is null) return Http.Err(400, "Invalid body");
        var etag = data.ETag();
        var d = new Depot
        {
