            var ex = await _db.Depots.AsNoTracking().IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == data.Id, ct);
            if (ex is null) return Http.Err(409, "Conflict");
            if (ex.DeletedAt != null) return Http.Err(410, "Gone");
            if (ex.CreateHash != etag && ex.ETag != etag) return Http.Err(409, "Id exists with different content");
            SetETag(ex.ETag);
            return Ok(Map(ex));
